module vending_machine(input logic clk,rst,item_button,input logic [2:0] item_selected,
input logic [3:0] coin_input,input logic cancel,
output logic dispense_item,return_change,output logic [4:0] item_price,change_amount,
output logic [2:0] dispense_item_id,output logic error,return_money);
typedef enum logic [2:0] {IDLE,ITEM_SELECTION,PAYMENT_VALIDATION,DISPENSING_ITEM,RETURN_CHANGE,RETURN_MONEY} state_t;
state_t state;
logic prev_button,prev_cancel;
logic [5:0] money;
logic [2:0] selected;
wire cancel_edge=cancel & ~prev_cancel;
wire valid_coin=coin_input==1 || coin_input==2 || coin_input==5 || coin_input==10;
always_ff @(posedge clk or posedge rst) begin
 if(rst) begin
 state<=IDLE; prev_button<=0;prev_cancel<=0;money<=0;selected<=0;
 dispense_item<=0;return_change<=0;item_price<=0;change_amount<=0;dispense_item_id<=0;error<=0;return_money<=0;
 end else begin
 prev_button<=item_button;prev_cancel<=cancel;
 dispense_item<=0;return_change<=0;error<=0;return_money<=0;
 if(cancel_edge && (state==ITEM_SELECTION || state==PAYMENT_VALIDATION)) begin error<=1;state<=RETURN_MONEY; end
 else case(state)
 IDLE: begin
 money<=0;item_price<=0;change_amount<=0;dispense_item_id<=0;
 if(item_button && !prev_button) state<=ITEM_SELECTION;
 else if(coin_input!=0) begin money<=coin_input;error<=1;state<=RETURN_MONEY;end
 end
 ITEM_SELECTION: begin
 if(item_selected>=1 && item_selected<=4) begin selected<=item_selected;item_price<=item_selected*5;state<=PAYMENT_VALIDATION;end
 else if(item_selected!=0) begin error<=1;state<=RETURN_MONEY;end
 end
 PAYMENT_VALIDATION: if(coin_input!=0) begin
 if(valid_coin) begin money<=money+coin_input;if(money+coin_input>=item_price) state<=DISPENSING_ITEM;end
 else begin error<=1;return_money<=1;money<=0;state<=IDLE;end
 end
 DISPENSING_ITEM: begin dispense_item<=1;dispense_item_id<=selected;
 change_amount<=money-item_price;if(money>item_price)state<=RETURN_CHANGE;else state<=IDLE;end
 RETURN_CHANGE: begin return_change<=1;state<=IDLE;end
 RETURN_MONEY: begin return_money<=money!=0;change_amount<=money;state<=IDLE;end
 default: state<=IDLE;
 endcase
 end
end
endmodule

module fir_filter(input logic clk,reset,input logic signed [15:0] input_sample,
output logic signed [15:0] output_sample,input logic signed [15:0] coeff0,coeff1,coeff2,coeff3);
logic signed [15:0] d1,d2,d3;
logic signed [31:0] acc,p1,p2;
always_ff @(posedge clk or posedge reset) begin
 if(reset) begin d1<=0;d2<=0;d3<=0;acc<=0;p1<=0;p2<=0;output_sample<=0;end
 else begin
 d1<=input_sample;d2<=d1;d3<=d2;
 acc<=input_sample*coeff0+d1*coeff1+d2*coeff2+d3*coeff3;
 p1<=acc;p2<=p1;output_sample<=p2[15:0];
 end
end
endmodule

module axi_register #(parameter ADDR_WIDTH=32, DATA_WIDTH=32)(
input logic clk_i,rst_n_i,input logic [ADDR_WIDTH-1:0] awaddr_i,input logic awvalid_i,
input logic [DATA_WIDTH-1:0] wdata_i,input logic wvalid_i,input logic [DATA_WIDTH/8-1:0] wstrb_i,
input logic bready_i,input logic [ADDR_WIDTH-1:0] araddr_i,input logic arvalid_i,rready_i,done_i,
output logic awready_o,wready_o,output logic [1:0] bresp_o,output logic bvalid_o,arready_o,
output logic [DATA_WIDTH-1:0] rdata_o,output logic rvalid_o,output logic [1:0] rresp_o,
output logic [19:0] beat_o,output logic start_o,writeback_o);
logic have_addr,have_data,done_q;
logic [11:0] addr;
logic [DATA_WIDTH-1:0] data_q;
logic [DATA_WIDTH/8-1:0] strb_q;
assign awready_o= !have_addr && !bvalid_o;
assign wready_o= !have_data && !bvalid_o;
assign arready_o= !rvalid_o;
always_ff @(posedge clk_i or negedge rst_n_i) begin
 if(!rst_n_i) begin have_addr<=0;have_data<=0;addr<=0;data_q<=0;strb_q<=0;done_q<=0;
 bvalid_o<=0;bresp_o<=0;rvalid_o<=0;rresp_o<=0;rdata_o<=0;beat_o<=0;start_o<=0;writeback_o<=0;end
 else begin
 if(done_i)done_q<=1;
 if(awready_o && awvalid_i)begin addr<=awaddr_i[11:0];have_addr<=1;end
 if(wready_o && wvalid_i)begin data_q<=wdata_i;strb_q<=wstrb_i;have_data<=1;end
 if(bvalid_o && bready_i)bvalid_o<=0;
 if(have_addr && have_data && !bvalid_o)begin
 have_addr<=0;have_data<=0;bvalid_o<=1;bresp_o<=0;
 case(addr)
 12'h100: if(&strb_q)beat_o<=20'(data_q);
 12'h200: if(&strb_q)start_o<=data_q[0];
 12'h300: if((&strb_q) && data_q[0])done_q<=0;
 12'h400: if(&strb_q)writeback_o<=data_q[0];
 default:bresp_o<=2'b10;
 endcase
 end
 if(rvalid_o && rready_i)rvalid_o<=0;
 if(arready_o && arvalid_i)begin
 rvalid_o<=1;rresp_o<=0;
 case(araddr_i[11:0])
 12'h100:rdata_o<=DATA_WIDTH'(beat_o);
 12'h200:rdata_o<=DATA_WIDTH'(start_o);
 12'h300:rdata_o<=DATA_WIDTH'(done_q | done_i);
 12'h400:rdata_o<=DATA_WIDTH'(writeback_o);
 12'h500:rdata_o<=DATA_WIDTH'(32'h00010001);
 default:begin rdata_o<=0;rresp_o<=2'b10;end
 endcase
 end
 end
end
endmodule

