module cache_mshr #(
    parameter INSTANCE_ID                   = "mo_mshr"             ,
    parameter MSHR_SIZE                     = 32                    ,
    parameter CS_LINE_ADDR_WIDTH            = 10                    ,
    parameter WORD_SEL_WIDTH                = 4                     ,
    parameter WORD_SIZE                     = 4                     ,
    // Derived parameters
    parameter MSHR_ADDR_WIDTH               = $clog2(MSHR_SIZE)     , // default = 5
    parameter TAG_WIDTH                     = 32 - (CS_LINE_ADDR_WIDTH+ $clog2(WORD_SIZE) + WORD_SEL_WIDTH), // default = 16
    parameter CS_WORD_WIDTH                 = WORD_SIZE * 8 ,// default = 32 
    parameter DATA_WIDTH                    = WORD_SEL_WIDTH + WORD_SIZE + CS_WORD_WIDTH + TAG_WIDTH // default =  4 + 4 + 32 + 16 = 56

    ) (
    input wire clk,
    input wire reset,

    // allocate
    input wire                          allocate_valid,
    output wire                         allocate_ready,
    input wire [CS_LINE_ADDR_WIDTH-1:0] allocate_addr,
    input wire                          allocate_rw,
    input wire [DATA_WIDTH-1:0]         allocate_data,
    output wire [MSHR_ADDR_WIDTH-1:0]   allocate_id,
    output wire                         allocate_pending,
    output wire [MSHR_ADDR_WIDTH-1:0]   allocate_previd,

    // finalize
    input wire                          finalize_valid,
    input wire [MSHR_ADDR_WIDTH-1:0]    finalize_id
);



reg [MSHR_SIZE-1:0] valid_q,next_valid;
reg [CS_LINE_ADDR_WIDTH-1:0] addresses [0:MSHR_SIZE-1];
reg [DATA_WIDTH-1:0] data_mem [0:MSHR_SIZE-1];
reg [MSHR_ADDR_WIDTH-1:0] next_id [0:MSHR_SIZE-1];
reg [MSHR_SIZE-1:0] writes;
reg [MSHR_ADDR_WIDTH-1:0] free_id,prev_id;
reg free_found,match_found;
reg [MSHR_ADDR_WIDTH-1:0] allocated_q,previous_q;
reg pending_q;
integer i,j;
always @* begin
 free_id=0;prev_id=0;free_found=0;match_found=0;
 for(integer k=0;k<MSHR_SIZE;k=k+1)begin
 if(!valid_q[k] && !free_found)begin free_id=k;free_found=1;end
 if(valid_q[k] && addresses[k]==allocate_addr && !next_valid[k] && !match_found)begin prev_id=k;match_found=1;end
 end
end
assign allocate_ready=free_found;
assign allocate_id=allocated_q;
assign allocate_pending=pending_q;
assign allocate_previd=previous_q;
always @(posedge clk) begin
 if(reset)begin valid_q<=0;next_valid<=0;writes<=0;allocated_q<=0;previous_q<=0;pending_q<=0;
 for(i=0;i<MSHR_SIZE;i=i+1)begin addresses[i]<=0;data_mem[i]<=0;next_id[i]<=0;end
 end else begin
 pending_q<=0;
 if(finalize_valid)begin
 valid_q[finalize_id]<=0;next_valid[finalize_id]<=0;
 for(j=0;j<MSHR_SIZE;j=j+1)if(valid_q[j] && next_valid[j] && next_id[j]==finalize_id)begin
 next_valid[j]<=next_valid[finalize_id];next_id[j]<=next_id[finalize_id];end
 end
 if(allocate_valid && allocate_ready)begin
 valid_q[free_id]<=1;next_valid[free_id]<=0;addresses[free_id]<=allocate_addr;
 data_mem[free_id]<=allocate_data;writes[free_id]<=allocate_rw;allocated_q<=free_id;
 pending_q<=match_found;previous_q<=prev_id;
 if(match_found && !(finalize_valid && finalize_id==prev_id))begin next_valid[prev_id]<=1;next_id[prev_id]<=free_id;end
 end
 end
end
endmodule
module leading_zero_cnt #(
    parameter DATA_WIDTH = 32,
    parameter REVERSE = 0 
)(
    input  [DATA_WIDTH -1:0] data,
    output  [$clog2(DATA_WIDTH)-1:0] leading_zeros,
    output all_zeros 
);
    localparam NIBBLES_NUM = DATA_WIDTH/4 ; 
    reg [NIBBLES_NUM-1 :0] all_zeros_flag ;
    reg [1:0]  zeros_cnt_per_nibble [NIBBLES_NUM-1 :0]  ;

    genvar i;
    integer k ;
    // Assign data/nibble 
    reg [3:0]  data_per_nibble [NIBBLES_NUM-1 :0]  ;
    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin
            always @* begin
                data_per_nibble[i] = data[(i*4)+3: (i*4)] ;
            end
        end
    endgenerate

    generate
        for (i=0; i < NIBBLES_NUM ; i=i+1) begin : g_nibble
            if (REVERSE) begin : g_trailing
                always @* begin
                        zeros_cnt_per_nibble[i] [1] = ~(data_per_nibble[i][1] | data_per_nibble[i][0]); 
                        zeros_cnt_per_nibble[i] [0] = (~data_per_nibble[i][0]) &
                                                      ((~data_per_nibble[i][2]) | data_per_nibble[i][1]);
                        all_zeros_flag[i] = (data_per_nibble[i] == 4'b0000);
                end
            end else begin :g_leading
                always @* begin
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][1] = ~(data_per_nibble[i][3] | data_per_nibble[i][2]); 
                    zeros_cnt_per_nibble[NIBBLES_NUM-1-i][0] = (~data_per_nibble[i][3]) &
                                     ((~data_per_nibble[i][1]) | data_per_nibble[i][2]);

                    all_zeros_flag[NIBBLES_NUM-1-i] = (data_per_nibble[i] == 4'b0000);
                end
            end
        end
    endgenerate



    reg [$clog2(NIBBLES_NUM)-1:0] index ; 
    reg [1:0]    choosen_nibbles_zeros_count ;
    reg [ $clog2(NIBBLES_NUM*4)-1:0] zeros_count_result ;
    wire [NIBBLES_NUM-1:0]         all_zeros_flag_decoded;

    assign all_zeros_flag_decoded[0] = all_zeros_flag[0] ;
    genvar j;
        generate
            for (j=1; j < NIBBLES_NUM; j=j+1) begin
                assign all_zeros_flag_decoded[j] = all_zeros_flag_decoded[j-1] & all_zeros_flag[j];
            end
        endgenerate

    always@ * begin
        index = 0 ;
        for ( k =0 ; k< NIBBLES_NUM ; k =k +1) begin
            index = index + all_zeros_flag_decoded[k] ;
        end
    end

    always@* begin
        choosen_nibbles_zeros_count = zeros_cnt_per_nibble[index]  ;  
        zeros_count_result = choosen_nibbles_zeros_count + (index <<2) ; 
    end

    assign leading_zeros =  zeros_count_result ;
    assign all_zeros = (data ==0) ;

endmodule

module copilot_rs_232 #(parameter HIGH=1'b1,LOW=1'b0,CLOCK_FREQ=100000000,BAUD_RATE=115200,REG_INPUT=1,BAUD_ACC_WIDTH=16)(
input clock,reset_neg,tx_datain_ready,Present_Processing_Completed,input [7:0] tx_datain,
output reg tx_transmitter,output wire tx_transmitter_valid);
reg busy;
reg [3:0] bit_index;
reg [9:0] frame;
wire baud_pulse;
assign tx_transmitter_valid=busy;
baud_rate_generator #(.CLOCK_FREQ(CLOCK_FREQ),.BAUD_RATE(BAUD_RATE),.BAUD_ACC_WIDTH(BAUD_ACC_WIDTH)) gen_baud(
.clock(clock),.reset_neg(reset_neg),.enable(busy && !Present_Processing_Completed),.baud_pulse(baud_pulse));
always @(posedge clock or negedge reset_neg)begin
 if(!reset_neg)begin busy<=0;bit_index<=0;frame<=10'h3ff;tx_transmitter<=1;end
 else if(Present_Processing_Completed)tx_transmitter<=1;
 else if(!busy)begin
 tx_transmitter<=1;
 if(tx_datain_ready)begin frame<={1'b1,tx_datain,1'b0};bit_index<=0;busy<=1;tx_transmitter<=0;end
 end else begin
 tx_transmitter<=frame[bit_index];
 if(baud_pulse)begin
 if(bit_index==9)begin busy<=0;tx_transmitter<=1;end
 else begin bit_index<=bit_index+1'b1;tx_transmitter<=frame[bit_index+1'b1];end
 end
 end
end
endmodule
module baud_rate_generator #(parameter CLOCK_FREQ=100000000,BAUD_RATE=115200,BAUD_ACC_WIDTH=16)(
input clock,reset_neg,enable,output reg baud_pulse);
localparam [BAUD_ACC_WIDTH:0] INC=((BAUD_RATE << (BAUD_ACC_WIDTH-4))+(CLOCK_FREQ >> 5))/(CLOCK_FREQ >> 4);
reg [BAUD_ACC_WIDTH:0] acc;
always @(posedge clock or negedge reset_neg)begin
 if(!reset_neg)begin acc<=0;baud_pulse<=0;end
 else if(enable)begin acc<={1'b0,acc[BAUD_ACC_WIDTH-1:0]}+INC;baud_pulse<=acc[BAUD_ACC_WIDTH];end
 else begin acc<=0;baud_pulse<=0;end
end
endmodule

module brent_kung_adder(
    input  logic [31:0] a,
    input  logic [31:0] b,
    input  logic carry_in,
    output logic [31:0] sum,
    output logic carry_out
);
    logic [31:0] P1, G1;
    logic [32:1] C;
    logic [15:0] G2, P2;
    logic [7:0] G3, P3;
    logic [3:0] G4, P4;
    logic [1:0] G5, P5;
    logic G6, P6;

    assign P1 = a ^ b;
    assign G1 = a & b;

    genvar i;
    generate
        for(i=0; i<=30; i=i+2) begin: second_stage  
            assign G2[i/2] = G1[i+1] | (P1[i+1] & G1[i]); 
            assign P2[i/2] = P1[i+1] & P1[i];
        end
    endgenerate

    generate
        for(i=0; i<=14; i=i+2) begin: third_stage   
            assign G3[i/2] = G2[i+1] | (P2[i+1] & G2[i]);
            assign P3[i/2] = P2[i+1] & P2[i];
        end
    endgenerate

    generate
        for(i=0; i<=6; i=i+2) begin: fourth_stage  
            assign G4[i/2] = G3[i+1] | (P3[i+1] & G3[i]);
            assign P4[i/2] = P3[i+1] & P3[i];
        end
    endgenerate

    generate
        for(i=0; i<=2; i=i+2) begin: fifth_stage  
            assign G5[i/2] = G4[i+1] | (P4[i+1] & G4[i]);
            assign P5[i/2] = P4[i+1] & P4[i];
        end
    endgenerate

    assign G6 = G5[1] | (P5[1] & G5[0]);
    assign P6 = P5[1] & P5[0];

    assign C[1] = G1[0] | (P1[0] & carry_in);
    assign C[2] = G2[0] | (P2[0] & carry_in);
    assign C[4] = G3[0] | (P3[0] & carry_in);
    assign C[8] = G4[0] | (P4[0] & carry_in);
    assign C[16] = G5[0] | (P5[0] & carry_in);
    assign C[32] = G6 | (P6 & carry_in);

    assign C[3] = G1[2] | (P1[2] & C[2]);
    assign C[5] = G1[4] | (P1[4] & C[4]);
    assign C[6] = G2[2] | (P2[2] & C[4]);
    assign C[7] = G1[6] | (P1[6] & C[6]);

    assign C[9] = G1[8] | (P1[8] & C[8]);
    assign C[10] = G2[4] | (P2[4] & C[8]);
    assign C[11] = G1[10] | (P1[10] & C[10]);
    assign C[12] = G3[2] | (P3[2] & C[8]);
    assign C[13] = G1[12] | (P1[12] & C[12]);
    assign C[14] = G2[6] | (P2[6] & C[12]);
    assign C[15] = G1[14] | (P1[14] & C[14]);

    assign C[17] = G1[16] | (P1[16] & C[16]);
    assign C[18] = G2[8] | (P2[8] & C[16]);
    assign C[19] = G1[18] | (P1[18] & C[18]);
    assign C[20] = G3[4] | (P3[4] & C[16]);
    assign C[21] = G1[20] | (P1[20] & C[20]);
    assign C[22] = G2[10] | (P2[10] & C[20]);
    assign C[23] = G1[22] | (P1[22] & C[22]);
    assign C[24] = G4[2] | (P4[2] & C[16]);
    assign C[25] = G1[24] | (P1[24] & C[24]);
    assign C[26] = G2[12] | (P2[12] & C[24]);
    assign C[27] = G1[26] | (P1[26] & C[26]);
    assign C[28] = G3[6] | (P3[6] & C[24]);
    assign C[29] = G1[28] | (P1[28] & C[28]);
    assign C[30] = G2[14] | (P2[14] & C[28]);
    assign C[31] = G1[30] | (P1[30] & C[30]);

    assign sum = P1 ^ {C[31:1], carry_in};
    assign carry_out = C[32];

endmodule

module sigma_delta_audio
(
  input   clk_sig,
  input   clk_en_sig,
  input  [14:0] load_data_sum,
  input  [14:0] read_data_sum,
  output  reg left_sig=0,
  output  reg right_sig=0
);

localparam DATA_WIDTH = 15;

localparam READ_WIDTH  = 4;
localparam A1_WIDTH = 2;
localparam A2_WIDTH = 5;

wire [DATA_WIDTH+2+0  -1:0] l_er0, r_er0;
reg  [DATA_WIDTH+2+0  -1:0] l_er0_prev=0, r_er0_prev=0;
wire [DATA_WIDTH+A1_WIDTH+2-1:0] l_aca1,  r_aca1;
wire [DATA_WIDTH+A2_WIDTH+2-1:0] l_aca2,  r_aca2;
reg  [DATA_WIDTH+A1_WIDTH+2-1:0] l_ac1=0, r_ac1=0;
reg  [DATA_WIDTH+A2_WIDTH+2-1:0] l_ac2=0, r_ac2=0;
wire [DATA_WIDTH+A2_WIDTH+3-1:0] l_quant, r_quant;

reg [24-1:0] seed_1 = 24'h654321;
reg [19-1:0] seed_2 = 19'h12345;
reg [24-1:0] s_sum=0, s_prev=0, s_out=0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_1)
      seed_1 <= 24'h654321;
    else
      seed_1 <= {seed_1[22:0], ~(seed_1[23] ^ seed_1[22] ^ seed_1[21] ^ seed_1[16])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (&seed_2)
      seed_2 <= 19'h12345;
    else
      seed_2 <= {seed_2[17:0], ~(seed_2[18] ^ seed_2[17] ^ seed_2[16] ^ seed_2[13] ^ seed_2[0])};
  end
end
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    s_sum  <= seed_1 + {5'b0, seed_2};
    s_prev <= s_sum;
    s_out  <= s_sum - s_prev;
  end
end

localparam INPUT_DATA=4;
reg  [INPUT_DATA+0-1:0] integer_count = 0;
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    integer_count <= integer_count + 4'd1;
  end
end

reg  [DATA_WIDTH+0-1:0] ldata_current=0, ldata_previous=0;
reg  [DATA_WIDTH+0-1:0] rdata_current=0, rdata_previous=0;
wire [DATA_WIDTH+1-1:0] load_data_step, read_data_step;
reg  [DATA_WIDTH+INPUT_DATA-1:0] load_data_int=0, read_data_int=0;
wire [DATA_WIDTH+0-1:0] load_data_int_out, read_data_int_out;
assign load_data_step = {ldata_current[DATA_WIDTH-1], ldata_current} - {ldata_previous[DATA_WIDTH-1], ldata_previous};
assign read_data_step = {rdata_current[DATA_WIDTH-1], rdata_current} - {rdata_previous[DATA_WIDTH-1], rdata_previous};
always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    if (~|integer_count) begin
      ldata_previous <= ldata_current;
      ldata_current  <= load_data_sum;
      rdata_previous <= rdata_current;
      rdata_current  <= read_data_sum;
      load_data_int  <= {ldata_current, {INPUT_DATA{1'b0}}};
      read_data_int  <= {rdata_current, {INPUT_DATA{1'b0}}};
    end else begin
      load_data_int  <= load_data_int + {{(INPUT_DATA-1){load_data_step[DATA_WIDTH+1-1]}}, load_data_step};
      read_data_int  <= read_data_int + {{(INPUT_DATA-1){read_data_step[DATA_WIDTH+1-1]}}, read_data_step};
    end
  end
end
assign load_data_int_out = load_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];
assign read_data_int_out = read_data_int[DATA_WIDTH+INPUT_DATA-1:INPUT_DATA];

wire [DATA_WIDTH+2-1:0] load_data_gain, read_data_gain;
assign load_data_gain = {load_data_int_out[DATA_WIDTH-1], load_data_int_out, 1'b0} + {{(2){load_data_int_out[DATA_WIDTH-1]}}, load_data_int_out};
assign read_data_gain = {read_data_int_out[DATA_WIDTH-1], read_data_int_out, 1'b0} + {{(2){read_data_int_out[DATA_WIDTH-1]}}, read_data_int_out};

assign l_aca1 = {{(A1_WIDTH){load_data_gain[DATA_WIDTH+2-1]}}, load_data_gain} - {{(A1_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} + l_ac1;
assign r_aca1 = {{(A1_WIDTH){read_data_gain[DATA_WIDTH+2-1]}}, read_data_gain} - {{(A1_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} + r_ac1;
assign l_aca2 = {{(A2_WIDTH-A1_WIDTH){l_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, l_aca1} - {{(A2_WIDTH){l_er0[DATA_WIDTH+2-1]}}, l_er0} - {{(A2_WIDTH+1){l_er0_prev[DATA_WIDTH+2-1]}}, l_er0_prev[DATA_WIDTH+2-1:1]} + l_ac2;
assign r_aca2 = {{(A2_WIDTH-A1_WIDTH){r_aca1[DATA_WIDTH+A1_WIDTH+2-1]}}, r_aca1} - {{(A2_WIDTH){r_er0[DATA_WIDTH+2-1]}}, r_er0} - {{(A2_WIDTH+1){r_er0_prev[DATA_WIDTH+2-1]}}, r_er0_prev[DATA_WIDTH+2-1:1]} + r_ac2;

always @ (posedge clk_sig) begin
  if (clk_en_sig) begin
    l_ac1 <= l_aca1;
    r_ac1 <= r_aca1;
    l_ac2 <= l_aca2;
    r_ac2 <= r_aca2;
  end
end

assign l_quant = {l_ac2[DATA_WIDTH+A2_WIDTH+2-1], l_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};
assign r_quant = {r_ac2[DATA_WIDTH+A2_WIDTH+2-1], r_ac2} + {{(DATA_WIDTH+A2_WIDTH+3-READ_WIDTH){s_out[READ_WIDTH-1]}}, s_out[READ_WIDTH-1:0]};

assign l_er0 = l_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};
assign r_er0 = r_quant[DATA_WIDTH+A2_WIDTH+3-1] ? {1'b1, {(DATA_WIDTH+2-1){1'b0}}} : {1'b0, {(DATA_WIDTH+2-1){1'b1}}};

always @ (posedge clk_sig)
begin
  if (clk_en_sig)
  begin
    if (~|load_data_gain)
    begin
      left_sig <= ~left_sig;
    end
    else
    begin
      left_sig <= ~l_er0[DATA_WIDTH+2-1];
    end

    if (~|read_data_gain)
    begin
      right_sig <= ~right_sig;
    end
    else
    begin
      right_sig <= ~r_er0[DATA_WIDTH+2-1];
    end
  end
end
endmodule

module vga_controller (
    input logic clock,      // 25 MHz
    input logic reset,      // Active high
    input logic [7:0] color_in, // Pixel color data (RRRGGGBB)
    output logic [9:0] next_x,  // x-coordinate of NEXT pixel that will be drawn
    output logic [9:0] next_y,  // y-coordinate of NEXT pixel that will be drawn
    output logic hsync,     // HSYNC (to VGA connector)
    output logic vsync,     // VSYNC (to VGA connector)
    output logic [7:0] red, // RED (to resistor DAC VGA connector)
    output logic [7:0] green, // GREEN (to resistor DAC to VGA connector)
    output logic [7:0] blue, // BLUE (to resistor DAC to VGA connector)
    output logic sync,      // SYNC to VGA connector
    output logic clk,       // CLK to VGA connector
    output logic blank,     // BLANK to VGA connector
    output logic [7:0] h_state, // States of Horizontal FSM
    output logic [7:0] v_state  // States of Vertical FSM
);

    parameter logic [9:0] H_ACTIVE  =  10'd640;
    parameter logic [9:0] H_FRONT   =  10'd16;
    parameter logic [9:0] H_PULSE   =  10'd96;
    parameter logic [9:0] H_BACK    =  10'd48;
    parameter logic [9:0] V_ACTIVE  =  10'd480;
    parameter logic [9:0] V_FRONT   =  10'd10;
    parameter logic [9:0] V_PULSE   =  10'd2;
    parameter logic [9:0] V_BACK    =  10'd33;
    parameter logic LOW   = 1'b0;
    parameter logic HIGH  = 1'b1;
    parameter logic [7:0] H_ACTIVE_STATE  = 8'd0;
    parameter logic [7:0] H_FRONT_STATE   = 8'd1;
    parameter logic [7:0] H_PULSE_STATE   = 8'd2;
    parameter logic [7:0] H_BACK_STATE    = 8'd3;
    parameter logic [7:0] V_ACTIVE_STATE  = 8'd0;
    parameter logic [7:0] V_FRONT_STATE   = 8'd1;
    parameter logic [7:0] V_PULSE_STATE   = 8'd2;
    parameter logic [7:0] V_BACK_STATE    = 8'd3;


    logic line_done;
    logic [9:0] h_counter;
    logic [9:0] v_counter;



logic [9:0] h_limit,v_limit;
logic h_known,v_known,h_last,v_last;
always_comb begin
 h_limit=0;v_limit=0;h_known=1;v_known=1;
 case(h_state)
 H_ACTIVE_STATE:h_limit=H_ACTIVE-10'd1;
 H_FRONT_STATE:h_limit=H_FRONT-10'd1;
 H_PULSE_STATE:h_limit=H_PULSE-10'd1;
 H_BACK_STATE:h_limit=H_BACK-10'd1;
 default:h_known=0;
 endcase
 case(v_state)
 V_ACTIVE_STATE:v_limit=V_ACTIVE-10'd1;
 V_FRONT_STATE:v_limit=V_FRONT-10'd1;
 V_PULSE_STATE:v_limit=V_PULSE-10'd1;
 V_BACK_STATE:v_limit=V_BACK-10'd1;
 default:v_known=0;
 endcase
end
assign h_last=h_counter==h_limit;
assign v_last=v_counter==v_limit;
always_ff @(posedge clock or posedge reset)begin
 if(reset)begin h_counter<=0;v_counter<=0;h_state<=H_ACTIVE_STATE;v_state<=V_ACTIVE_STATE;line_done<=LOW;end
 else begin
 if(h_known)begin
 h_counter<=h_last ? 10'd0 : h_counter+10'd1;
 hsync<=(h_state==H_PULSE_STATE)?LOW:HIGH;
 case(h_state)
 H_ACTIVE_STATE:begin line_done<=LOW;if(h_last)h_state<=H_FRONT_STATE;end
 H_FRONT_STATE:if(h_last)h_state<=H_PULSE_STATE;
 H_PULSE_STATE:if(h_last)h_state<=H_BACK_STATE;
 H_BACK_STATE:begin line_done<=h_last?HIGH:LOW;if(h_last)h_state<=H_ACTIVE_STATE;end
 endcase
 end
 if(v_known)begin
 vsync<=(v_state==V_PULSE_STATE)?LOW:HIGH;
 if(line_done==HIGH)begin
 v_counter<=v_last ? 10'd0 : v_counter+10'd1;
 if(v_last)case(v_state)
 V_ACTIVE_STATE:v_state<=V_FRONT_STATE;
 V_FRONT_STATE:v_state<=V_PULSE_STATE;
 V_PULSE_STATE:v_state<=V_BACK_STATE;
 V_BACK_STATE:v_state<=V_ACTIVE_STATE;
 endcase
 end
 end
 if(h_state==H_ACTIVE_STATE && v_state==V_ACTIVE_STATE)begin
 red<={color_in[7:5],5'd0};green<={color_in[4:2],5'd0};blue<={color_in[1:0],6'd0};end
 else begin red<=0;green<=0;blue<=0;end
 end
end

    assign clk = clock;
    assign sync = 1'b0;
    assign blank = hsync & vsync;

    assign next_x = (h_state == H_ACTIVE_STATE) ? h_counter : 10'd0;
    assign next_y = (v_state == V_ACTIVE_STATE) ? v_counter : 10'd0;

endmodule
